import React, { lazy, memo, useEffect, useMemo, useState } from 'react';
import { HashRouter, Switch, Route, Redirect, useHistory, useParams } from 'react-router-dom';
import utils from '@/environments/utils';
import PageContent from './PageContent';
import './style.less';
import store from './store';
import { RouteProps } from '@/types/menu';
import { Spin } from '@arco-design/web-react';
import lazyload from '@/utils/lazyload';
import app from '@/store/app';
const tenant = localStorage.getItem('tenant')

interface PageComponentProps {
    pageId: string;
}

function getFlattenRoutes(routes: RouteProps[]) {
    const res:any[] = [];
    function travel(_routes: RouteProps[]) {
        _routes.forEach((route) => {
            if (Array.isArray(route.children) && route.children.length) {
                travel(route.children);
            }
            if(route.pageId){
                route.component = () => <PageContent key={route.pageId} pageId={route.pageId} />
                res.push(route);
            }
        });
    }
    travel(routes);
    return res;
}

const PageRouter = () => {



    const flattenRoutes = useMemo(() => getFlattenRoutes(store.routes), [])
    console.log('flattenRoutes', flattenRoutes)
    utils.history = useHistory();

    const defaultRoute = useMemo(() => {
        if(!flattenRoutes.length) return '/';
        return flattenRoutes[0].paths;
    }, [flattenRoutes])

    const routeChildren = useMemo(() => {
        return flattenRoutes.map((route, index) => {
            return (
                <Route
                    key={index}
                    path={route.paths}
                    component={route.component}
                />
            );
        })
    },[flattenRoutes])

    return (
        <Switch>
            {routeChildren}
            <Route exact path="/">
                <Redirect to={defaultRoute} />
            </Route>
        </Switch>
    )
}

const Index = () => {
    const [isReady, setIsReady] = useState(false);
    const params: any = useParams();

    useEffect(() => {
        app.appId = params.id;
        store.init().then(async () => {
            await import('@/layout/init');
            setIsReady(true);
        })
    },[])


    if(!isReady) return <Spin />;
    return (
        <HashRouter basename={`/view`}>
            <PageRouter />
        </HashRouter>
    )
}

export default Index;