import React from 'react';
import ajax from '@/utils/ajax';
import { action, observable } from 'mobx';
import { convertToTree, getSpecificValues } from '@/utils';
import app from '@/store/app';


class Store {
    
    // @observable routes = [];
    routes = [];
    setRoutes = (list) => {
        this.routes = getSpecificValues(
            list,
            (item, parentItem) => {
                const { paths } = parentItem || {};
                return {
                    ...item,
                    paths: `${paths? `${paths}/` : '/'}${item.path}`
                }
            }
        );
    }


    /** 初始化 */
    init = async () => {
        await this.getMenuList();
    }



    /**
     * 获取路由
     */
    getMenuList = async () => {
        return ajax.post('/apijson/get', {
            "Menu[]":{
                "count":0,
                "Menu":{
                    // classId: app.appId,
                    "@order":"sort+"
                }
            }
        }).then((res) => {
            this.setRoutes(convertToTree(res.Menu));
        })
    }

}

export default new Store();